-- Carregue o CSV do lote em `SEU_PROJETO.logistica._stage_armazens` e execute este MERGE.
MERGE `SEU_PROJETO.logistica.armazens` T
USING `SEU_PROJETO.logistica._stage_armazens` S
ON T.hash_registro = S.hash_registro
WHEN NOT MATCHED THEN
  INSERT (`identificacao_armazem`, `especie_armazem`, `tipo_armazem`, `tipo_entidade`, `tipo_pessoa`, `municipio_original`, `municipio`, `cod_ibge`, `uf`, `capacidade_estatica_t`, `capacidade_expedicao_t`, `capacidade_recepcao_t`, `latitude`, `longitude`, `nome_armazenador`, `endereco`, `email`, `fonte`, `tipo_dado`, `tipo_registro`, `competencia`, `data_referencia`, `data_publicacao`, `data_coleta`, `arquivo_origem`, `hash_arquivo_sha256`, `source_id`, `source_url`, `data_snapshot`, `snapshot_basis`, `hash_registro`, `hash_chave_natural`, `arquivo_tamanho_bytes`) VALUES (S.`identificacao_armazem`, S.`especie_armazem`, S.`tipo_armazem`, S.`tipo_entidade`, S.`tipo_pessoa`, S.`municipio_original`, S.`municipio`, S.`cod_ibge`, S.`uf`, S.`capacidade_estatica_t`, S.`capacidade_expedicao_t`, S.`capacidade_recepcao_t`, S.`latitude`, S.`longitude`, S.`nome_armazenador`, S.`endereco`, S.`email`, S.`fonte`, S.`tipo_dado`, S.`tipo_registro`, S.`competencia`, S.`data_referencia`, S.`data_publicacao`, S.`data_coleta`, S.`arquivo_origem`, S.`hash_arquivo_sha256`, S.`source_id`, S.`source_url`, S.`data_snapshot`, S.`snapshot_basis`, S.`hash_registro`, S.`hash_chave_natural`, S.`arquivo_tamanho_bytes`);
